```typescript
// app/services/queue.server.ts

type JobHandler = (payload: unknown) => Promise<void>;

interface QueuedJob {
  id: string;
  type: string;
  payload: unknown;
  attempts: number;
  maxAttempts: number;
  createdAt: Date;
}

class InMemoryQueue {
  private handlers = new Map<string, JobHandler>();
  private processing = false;
  private queue: QueuedJob[] = [];
  private concurrency = 3;
  private activeCount = 0;

  register(jobType: string, handler: JobHandler): void {
    this.handlers.set(jobType, handler);
  }

  async enqueue(jobType: string, payload: unknown, maxAttempts = 3): Promise<string> {
    const id = crypto.randomUUID();
    this.queue.push({ id, type: jobType, payload, attempts: 0, maxAttempts, createdAt: new Date() });
    this.processNext();
    return id;
  }

  private async processNext(): Promise<void> {
    if (this.activeCount >= this.concurrency) return;
    const job = this.queue.shift();
    if (!job) return;

    this.activeCount++;
    const handler = this.handlers.get(job.type);
    if (!handler) {
      console.error(`No handler for job type: ${job.type}`);
      this.activeCount--;
      return;
    }

    try {
      await handler(job.payload);
    } catch (error) {
      job.attempts++;
      if (job.attempts < job.maxAttempts) {
        // Re-enqueue with exponential backoff
        const delayMs = Math.pow(2, job.attempts) * 1000;
        setTimeout(() => {
          this.queue.push(job);
          this.processNext();
        }, delayMs);
      } else {
        console.error(`Job ${job.id} (${job.type}) failed after ${job.maxAttempts} attempts:`, error);
      }
    } finally {
      this.activeCount--;
      this.processNext();
    }
  }
}

export const jobQueue = new InMemoryQueue();
```

### Option B: Prisma-Backed Queue (Durable)

For critical jobs that must survive server restarts:

```prisma
model JobQueue {
  id          String   @id @default(cuid())
  type        String
  payload     String   // JSON
  status      String   @default("pending") // pending, processing, completed, failed
  attempts    Int      @default(0)
  maxAttempts Int      @default(3)
  error       String?
  runAfter    DateTime @default(now())
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
  @@index([status, runAfter])
  @@index([type, status])
}
