```typescript
// app/services/durable-queue.server.ts

class DurableQueue {
  private handlers = new Map<string, JobHandler>();
  private polling = false;
  private pollIntervalMs = 5000;

  register(jobType: string, handler: JobHandler): void {
    this.handlers.set(jobType, handler);
  }

  async enqueue(jobType: string, payload: unknown, options?: { maxAttempts?: number; delayMs?: number }): Promise<string> {
    const job = await prisma.jobQueue.create({
      data: {
        type: jobType,
        payload: JSON.stringify(payload),
        maxAttempts: options?.maxAttempts ?? 3,
        runAfter: options?.delayMs ? new Date(Date.now() + options.delayMs) : new Date(),
      },
    });
    if (!this.polling) this.startPolling();
    return job.id;
  }

  private startPolling(): void {
    this.polling = true;
    setInterval(() => this.processBatch(), this.pollIntervalMs);
  }

  private async processBatch(): Promise<void> {
    // Claim up to 5 pending jobs atomically
    const jobs = await prisma.$transaction(async (tx) => {
      const pending = await tx.jobQueue.findMany({
        where: { status: "pending", runAfter: { lte: new Date() } },
        orderBy: { createdAt: "asc" },
        take: 5,
      });
      if (pending.length === 0) return [];
      await tx.jobQueue.updateMany({
        where: { id: { in: pending.map(j => j.id) } },
        data: { status: "processing" },
      });
      return pending;
    });

    for (const job of jobs) {
      const handler = this.handlers.get(job.type);
      if (!handler) continue;
      try {
        await handler(JSON.parse(job.payload));
        await prisma.jobQueue.update({ where: { id: job.id }, data: { status: "completed" } });
      } catch (error) {
        const attempts = job.attempts + 1;
        if (attempts >= job.maxAttempts) {
          await prisma.jobQueue.update({
            where: { id: job.id },
            data: { status: "failed", attempts, error: String(error) },
          });
        } else {
          const backoffMs = Math.pow(2, attempts) * 1000;
          await prisma.jobQueue.update({
            where: { id: job.id },
            data: { status: "pending", attempts, runAfter: new Date(Date.now() + backoffMs) },
          });
        }
      }
    }
  }
}

export const durableQueue = new DurableQueue();
