): Promise<string> {
  // Validate before upload
  validateImageFile(file);

  const buffer = Buffer.from(await file.arrayBuffer());
  const staged = await createStagedUpload(admin, file.name, file.type, file.size);
  await uploadToStagedTarget(staged, buffer, file.name, file.type);
  const cdnUrl = await registerUploadedFile(admin, staged.resourceUrl, altText);
  return cdnUrl;
}
