## File Validation

```typescript
const ALLOWED_IMAGE_TYPES = ["image/jpeg", "image/png", "image/webp", "image/gif"];
const MAX_IMAGE_SIZE = 5 * 1024 * 1024; // 5MB
const MAX_CSV_SIZE = 10 * 1024 * 1024;  // 10MB
const MAX_JSON_SIZE = 5 * 1024 * 1024;  // 5MB

function validateImageFile(file: File): void {
  if (!ALLOWED_IMAGE_TYPES.includes(file.type)) {
    throw new Error(`Invalid image type: ${file.type}. Allowed: ${ALLOWED_IMAGE_TYPES.join(", ")}`);
  }
  if (file.size > MAX_IMAGE_SIZE) {
    throw new Error(`Image too large: ${(file.size / 1024 / 1024).toFixed(1)}MB. Max: 5MB`);
  }
  if (file.size === 0) {
    throw new Error("File is empty");
  }
}

function validateCsvFile(file: File): void {
  if (file.type !== "text/csv" && !file.name.endsWith(".csv")) {
    throw new Error("File must be a CSV");
  }
  if (file.size > MAX_CSV_SIZE) {
    throw new Error(`CSV too large: ${(file.size / 1024 / 1024).toFixed(1)}MB. Max: 10MB`);
  }
}

function validateJsonFile(file: File): void {
  if (file.type !== "application/json" && !file.name.endsWith(".json")) {
    throw new Error("File must be JSON");
  }
  if (file.size > MAX_JSON_SIZE) {
    throw new Error(`JSON too large: ${(file.size / 1024 / 1024).toFixed(1)}MB. Max: 5MB`);
  }
}
