```typescript
export async function exportResponsesToCSV(quizId: string): Promise<string> {
  const responses = await prisma.quizResponse.findMany({
    where: { quizId },
    include: { resultPage: { select: { title: true } } },
    orderBy: { createdAt: "desc" },
  });

  const headers = ["Response ID", "Session ID", "Email", "Total Score", "Matched Tags", "Result Page", "Completed At"];
  const rows = responses.map(r => [
    r.id,
    r.sessionId,
    r.email ?? "",
    String(r.totalScore ?? 0),
    r.matchedTags ?? "{}",
    r.resultPage?.title ?? "N/A",
    r.completedAt?.toISOString() ?? "",
  ]);

  // Escape CSV values (handle commas, quotes, newlines)
  const escapeCSV = (val: string) => {
    if (val.includes(",") || val.includes('"') || val.includes("\n")) {
      return `"${val.replace(/"/g, '""')}"`;
    }
    return val;
  };

  const csv = [
    headers.map(escapeCSV).join(","),
    ...rows.map(row => row.map(escapeCSV).join(",")),
  ].join("\n");

  return csv;
}

