## CSV Import: Quiz Responses (Bulk)

```typescript
export async function importResponsesFromCSV(
  csvContent: string,
  quizId: string
): Promise<{ imported: number; errors: string[] }> {
  const lines = csvContent.split("\n").filter(l => l.trim());
  const headers = parseCSVLine(lines[0]);
  const errors: string[] = [];
  const toInsert: QuizResponseCreate[] = [];

  for (let i = 1; i < lines.length; i++) {
    try {
      const values = parseCSVLine(lines[i]);
      const row = Object.fromEntries(headers.map((h, idx) => [h, values[idx] ?? ""]));
      toInsert.push({
        quizId,
        sessionId: row["Session ID"] || `import-${crypto.randomUUID()}`,
        email: row["Email"] || null,
        totalScore: parseInt(row["Total Score"]) || 0,
        matchedTags: row["Matched Tags"] || "{}",
        answers: "[]",
        completedAt: row["Completed At"] ? new Date(row["Completed At"]) : new Date(),
      });
    } catch (err) {
      errors.push(`Row ${i + 1}: ${String(err)}`);
    }
  }

  if (toInsert.length > 0) {
    await prisma.quizResponse.createMany({ data: toInsert, skipDuplicates: true });
  }

  return { imported: toInsert.length, errors };
}

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
      else { inQuotes = !inQuotes; }
    } else if (char === "," && !inQuotes) {
      result.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }
  result.push(current.trim());
  return result;
}
