// Import quiz from template JSON
export async function importQuizFromTemplate(
  jsonContent: string,
  shopId: string
): Promise<string> {
  const template = JSON.parse(jsonContent);
  if (template.version !== "1.0") throw new Error(`Unsupported template version: ${template.version}`);

  const quizId = await prisma.$transaction(async (tx) => {
    const quiz = await tx.quiz.create({
      data: {
        shopId,
        title: `${template.quiz.title} (Imported)`,
        slug: `imported-${Date.now()}`,
        description: template.quiz.description,
        scoringType: template.quiz.scoringType,
        settings: template.quiz.settings,
        status: "draft",
      },
    });

    for (const q of template.quiz.questions) {
      const question = await tx.question.create({
        data: { quizId: quiz.id, type: q.type, title: q.title, description: q.description,
          position: q.position, isRequired: q.isRequired, weight: q.weight, imageUrl: q.imageUrl },
      });
      await tx.answer.createMany({
        data: q.answers.map((a: any) => ({
          questionId: question.id, text: a.text, position: a.position,
          scoreValue: a.scoreValue, tags: a.tags, imageUrl: a.imageUrl,
        })),
      });
    }

    for (const rp of template.quiz.resultPages) {
      await tx.resultPage.create({
        data: { quizId: quiz.id, ...rp, productIds: "[]" },
      });
    }

    if (template.quiz.widgetConfig) {
      await tx.widgetConfig.create({
        data: { quizId: quiz.id, ...template.quiz.widgetConfig },
      });
    }

    return quiz.id;
  });

  return quizId;
}
