## Bulk File Operations

For quizzes with many image-choice questions, support batch upload:

```typescript
export async function uploadMultipleImages(
  admin: AdminApiContext,
  files: File[]
): Promise<{ filename: string; url: string; error?: string }[]> {
  const results: { filename: string; url: string; error?: string }[] = [];

  // Process in batches of 5 to avoid rate limits
  for (let i = 0; i < files.length; i += 5) {
    const batch = files.slice(i, i + 5);
    const batchResults = await Promise.allSettled(
      batch.map(async (file) => {
        const url = await uploadQuizImage(admin, file, file.name);
        return { filename: file.name, url };
      })
    );

    for (const result of batchResults) {
      if (result.status === "fulfilled") {
        results.push(result.value);
      } else {
        results.push({ filename: "unknown", url: "", error: result.reason?.message ?? "Upload failed" });
      }
    }
  }

  return results;
}
